1	/**
2	 * Data Retention & GDPR Compliance System
3	 * 
4	 * Handles:
5	 * - Configurable retention policies
6	 * - Automatic data expiration
7	 * - GDPR data subject requests (export, delete)
8	 * - Audit trail preservation
9	 * - Right to be forgotten
10	 * 
11	 * "Proof data has a lifecycle"
12	 */
13	
14	import crypto from "crypto";
15	import { getDb } from "../db";
16	import { eq, and } from "drizzle-orm";
17	import {
18	  dataSubjectRequests,
19	  users,
20	  governanceAuditLog,
21	  conversationSessions,
22	  conversationTurns,
23	  emotionalHistory,
24	  emotionalPatterns,
25	  apiUsage,
26	} from "../../drizzle/schema";
27	
28	// ============================================================================
29	// TYPES
30	// ============================================================================
31	
32	export interface RetentionPolicy {
33	  policyId: string;
34	  orgId: string;
35	  name: string;
36	  
37	  // Data categories
38	  dataCategory: "audit_logs" | "proofs" | "artifacts" | "user_data" | "analytics";
39	  
40	  // Retention settings
41	  retentionDays: number;
42	  archiveAfterDays: number | null;
43	  deleteAfterDays: number;
44	  
45	  // Legal hold
46	  legalHoldEnabled: boolean;
47	  legalHoldReason: string | null;
48	  
49	  // Compliance
50	  complianceFramework: "gdpr" | "ccpa" | "hipaa" | "sox" | "custom";
51	  
52	  // Status
53	  active: boolean;
54	  createdAt: Date;
55	  updatedAt: Date;
56	}
57	
58	export interface DataSubjectRequest {
59	  requestId: string;
60	  orgId: string;
61	  
62	  // Subject identification
63	  subjectId: string;
64	  subjectEmail: string;
65	  
66	  // Request details
67	  requestType: "export" | "delete" | "access" | "rectify" | "restrict";
68	  requestedAt: Date;
69	  deadline: Date;
70	  
71	  // Status
72	  status: "pending" | "processing" | "completed" | "rejected";
73	  completedAt: Date | null;
74	  
75	  // Result
76	  result: DataSubjectResult | null;
77	  
78	  // Audit
79	  processedBy: string | null;
80	  notes: string;
81	}
82	
83	export interface DataSubjectResult {
84	  // For export requests
85	  exportUrl: string | null;
86	  exportExpiresAt: Date | null;
87	  
88	  // For delete requests
89	  deletedRecords: number;
90	  retainedRecords: number;
91	  retentionReason: string | null;
92	  
93	  // Verification
94	  verificationHash: string;
95	  completedAt: Date;
96	}
97	
98	export interface DataRecord {
99	  recordId: string;
100	  orgId: string;
101	  subjectId: string | null;
102	  
103	  // Data
104	  dataCategory: RetentionPolicy["dataCategory"];
105	  data: Record<string, unknown>;
106	  
107	  // Lifecycle
108	  createdAt: Date;
109	  expiresAt: Date;
110	  archivedAt: Date | null;
111	  deletedAt: Date | null;
112	  
113	  // Legal hold
114	  legalHold: boolean;
115	  
116	  // Metadata
117	  retentionPolicyId: string;
118	}
119	
120	export interface ComplianceReport {
121	  reportId: string;
122	  orgId: string;
123	  
124	  // Coverage
125	  framework: RetentionPolicy["complianceFramework"];
126	  reportPeriod: { start: Date; end: Date };
127	  
128	  // Metrics
129	  totalRecords: number;
130	  expiredRecords: number;
131	  archivedRecords: number;
132	  deletedRecords: number;
133	  
134	  // DSR metrics
135	  totalDSRs: number;
136	  completedDSRs: number;
137	  averageResponseTime: number;
138	  
139	  // Issues
140	  issues: string[];
141	  recommendations: string[];
142	  
143	  // Generated
144	  generatedAt: Date;
145	  generatedBy: string;
146	}
147	
148	// ============================================================================
149	// DATA RETENTION SERVICE
150	// ============================================================================
151	
152	export class DataRetentionService {
153	  private policies: Map<string, RetentionPolicy> = new Map();
154	  private requests: Map<string, DataSubjectRequest> = new Map();
155	  private records: Map<string, DataRecord> = new Map();
156	  private auditLog: Array<{
157	    timestamp: Date;
158	    action: string;
159	    actor: string;
160	    details: string;
161	    subjectId: string | null;
162	  }> = [];
163	
164	  // GDPR deadline (30 days)
165	  private dsrDeadlineDays = 30;
166	
167	  // ============================================================================
168	  // RETENTION POLICIES
169	  // ============================================================================
170	
171	  /**
172	   * Create a retention policy
173	   */
174	  createPolicy(params: {
175	    orgId: string;
176	    name: string;
177	    dataCategory: RetentionPolicy["dataCategory"];
178	    retentionDays: number;
179	    archiveAfterDays?: number;
180	    deleteAfterDays: number;
181	    complianceFramework: RetentionPolicy["complianceFramework"];
182	  }): RetentionPolicy {
183	    const policy: RetentionPolicy = {
184	      policyId: crypto.randomUUID(),
185	      orgId: params.orgId,
186	      name: params.name,
187	      dataCategory: params.dataCategory,
188	      retentionDays: params.retentionDays,
189	      archiveAfterDays: params.archiveAfterDays ?? null,
190	      deleteAfterDays: params.deleteAfterDays,
191	      legalHoldEnabled: false,
192	      legalHoldReason: null,
193	      complianceFramework: params.complianceFramework,
194	      active: true,
195	      createdAt: new Date(),
196	      updatedAt: new Date(),
197	    };
198	    
199	    this.policies.set(policy.policyId, policy);
200	    this.logAudit("POLICY_CREATED", "system", `Retention policy '${params.name}' created`, null);
201	    
202	    return policy;
203	  }
204	
205	  /**
206	   * Get policies for an org
207	   */
208	  getPolicies(orgId: string): RetentionPolicy[] {
209	    return Array.from(this.policies.values()).filter(p => p.orgId === orgId);
210	  }
211	
212	  /**
213	   * Enable legal hold on a policy
214	   */
215	  enableLegalHold(policyId: string, reason: string): RetentionPolicy {
216	    const policy = this.policies.get(policyId);
217	    if (!policy) {
218	      throw new Error(`Policy ${policyId} not found`);
219	    }
220	    
221	    policy.legalHoldEnabled = true;
222	    policy.legalHoldReason = reason;
223	    policy.updatedAt = new Date();
224	    
225	    this.logAudit("LEGAL_HOLD_ENABLED", "system", `Legal hold enabled on policy ${policyId}: ${reason}`, null);
226	    
227	    return policy;
228	  }
229	
230	  /**
231	   * Disable legal hold on a policy
232	   */
233	  disableLegalHold(policyId: string): RetentionPolicy {
234	    const policy = this.policies.get(policyId);
235	    if (!policy) {
236	      throw new Error(`Policy ${policyId} not found`);
237	    }
238	    
239	    policy.legalHoldEnabled = false;
240	    policy.legalHoldReason = null;
241	    policy.updatedAt = new Date();
242	    
243	    this.logAudit("LEGAL_HOLD_DISABLED", "system", `Legal hold disabled on policy ${policyId}`, null);
244	    
245	    return policy;
246	  }
247	
248	  // ============================================================================
249	  // DATA RECORDS
250	  // ============================================================================
251	
252	  /**
253	   * Store a data record with retention
254	   */
255	  storeRecord(params: {
256	    orgId: string;
257	    subjectId?: string;
258	    dataCategory: RetentionPolicy["dataCategory"];
259	    data: Record<string, unknown>;
260	    policyId: string;
261	  }): DataRecord {
262	    const policy = this.policies.get(params.policyId);
263	    if (!policy) {
264	      throw new Error(`Policy ${params.policyId} not found`);
265	    }
266	    
267	    const now = new Date();
268	    const expiresAt = new Date(now.getTime() + policy.retentionDays * 24 * 60 * 60 * 1000);
269	    
270	    const record: DataRecord = {
271	      recordId: crypto.randomUUID(),
272	      orgId: params.orgId,
273	      subjectId: params.subjectId ?? null,
274	      dataCategory: params.dataCategory,
275	      data: params.data,
276	      createdAt: now,
277	      expiresAt,
278	      archivedAt: null,
279	      deletedAt: null,
280	      legalHold: policy.legalHoldEnabled,
281	      retentionPolicyId: params.policyId,
282	    };
283	    
284	    this.records.set(record.recordId, record);
285	    return record;
286	  }
287	
288	  /**
289	   * Get records for a subject
290	   */
291	  getRecordsForSubject(orgId: string, subjectId: string): DataRecord[] {
292	    return Array.from(this.records.values())
293	      .filter(r => r.orgId === orgId && r.subjectId === subjectId && !r.deletedAt);
294	  }
295	
296	  /**
297	   * Process expired records
298	   */
299	  processExpiredRecords(): {
300	    archived: number;
301	    deleted: number;
302	    retained: number;
303	  } {
304	    const now = new Date();
305	    let archived = 0;
306	    let deleted = 0;
307	    let retained = 0;
308	    
309	    for (const record of this.records.values()) {
310	      if (record.deletedAt) continue;
311	      
312	      const policy = this.policies.get(record.retentionPolicyId);
313	      if (!policy) continue;
314	      
315	      // Check legal hold
316	      if (record.legalHold || policy.legalHoldEnabled) {
317	        retained++;
318	        continue;
319	      }
320	      
321	      const ageMs = now.getTime() - record.createdAt.getTime();
322	      const ageDays = ageMs / (24 * 60 * 60 * 1000);
323	      
324	      // Check for deletion
325	      if (ageDays >= policy.deleteAfterDays) {
326	        record.deletedAt = now;
327	        deleted++;
328	        this.logAudit("RECORD_DELETED", "system", `Record ${record.recordId} deleted per policy`, record.subjectId);
329	        continue;
330	      }
331	      
332	      // Check for archival
333	      if (policy.archiveAfterDays && ageDays >= policy.archiveAfterDays && !record.archivedAt) {
334	        record.archivedAt = now;
335	        archived++;
336	        this.logAudit("RECORD_ARCHIVED", "system", `Record ${record.recordId} archived per policy`, record.subjectId);
337	      }
338	    }
339	    
340	    return { archived, deleted, retained };
341	  }
342	
343	  // ============================================================================
344	  // DATA SUBJECT REQUESTS (GDPR)
345	  // ============================================================================
346	
347	  /**
348	   * Create a data subject request — persists to DB and in-memory map.
349	   */
350	  async createDSR(params: {
351	    orgId: string;
352	    subjectId: string;
353	    subjectEmail: string;
354	    requestType: DataSubjectRequest["requestType"];
355	  }): Promise<DataSubjectRequest> {
356	    const now = new Date();
357	    const deadline = new Date(now.getTime() + this.dsrDeadlineDays * 24 * 60 * 60 * 1000);
358	
359	    const request: DataSubjectRequest = {
360	      requestId: crypto.randomUUID(),
361	      orgId: params.orgId,
362	      subjectId: params.subjectId,
363	      subjectEmail: params.subjectEmail,
364	      requestType: params.requestType,
365	      requestedAt: now,
366	      deadline,
367	      status: "pending",
368	      completedAt: null,
369	      result: null,
370	      processedBy: null,
371	      notes: "",
372	    };
373	
374	    // Persist to database
375	    try {
376	      const db = await getDb();
377	      await db.insert(dataSubjectRequests).values({
378	        id: request.requestId,
379	        orgId: request.orgId,
380	        subjectId: request.subjectId,
381	        subjectEmail: request.subjectEmail,
382	        requestType: request.requestType,
383	        status: request.status,
384	        deadline: request.deadline,
385	        notes: request.notes,
386	      });
387	    } catch (err) {
388	      // Log but don't fail — keep in-memory fallback
389	      this.logAudit("DSR_DB_WRITE_FAILED", "system", `Failed to persist DSR to DB: ${(err as Error).message}`, params.subjectId);
390	    }
391	
392	    this.requests.set(request.requestId, request);
393	    this.logAudit("DSR_CREATED", "system", `DSR ${params.requestType} created for subject ${params.subjectId}`, params.subjectId);
394	
395	    return request;
396	  }
397	
398	  /**
399	   * Process a data subject request — performs real DB queries/deletes and
400	   * updates the DSR status in the database.
401	   */
402	  async processDSR(requestId: string, processedBy: string): Promise<DataSubjectRequest> {
403	    const request = this.requests.get(requestId);
404	    if (!request) {
405	      throw new Error(`DSR ${requestId} not found`);
406	    }
407	
408	    if (request.status !== "pending") {
409	      throw new Error(`DSR ${requestId} is not pending`);
410	    }
411	
412	    request.status = "processing";
413	    request.processedBy = processedBy;
414	
415	    // Update DB status to "processing"
416	    await this.updateDSRInDb(requestId, { status: "processing", processedBy });
417	
418	    // Process based on type
419	    switch (request.requestType) {
420	      case "export":
421	        request.result = await this.processExportRequest(request);
422	        break;
423	      case "delete":
424	        request.result = await this.processDeleteRequest(request);
425	        break;
426	      case "access":
427	        request.result = await this.processAccessRequest(request);
428	        break;
429	      case "restrict":
430	        request.result = await this.processRestrictRequest(request);
431	        break;
432	      case "rectify":
433	        // Rectification requires manual handling
434	        request.notes = "Rectification request requires manual review";
435	        break;
436	    }
437	
438	    request.status = "completed";
439	    request.completedAt = new Date();
440	
441	    // Update DB status to "completed"
442	    await this.updateDSRInDb(requestId, {
443	      status: "completed",
444	      completedAt: request.completedAt,
445	      result: request.result ? JSON.stringify(request.result) : null,
446	      notes: request.notes,
447	    });
448	
449	    this.logAudit("DSR_COMPLETED", processedBy, `DSR ${request.requestType} completed for subject ${request.subjectId}`, request.subjectId);
450	
451	    return request;
452	  }
453	
454	  /**
455	   * Process export request (right to data portability).
456	   * Queries all user-related data from the database and returns it as a
457	   * JSON bundle.
458	   */
459	  private async processExportRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
460	    // Collect in-memory records
461	    const inMemoryRecords = this.getRecordsForSubject(request.orgId, request.subjectId);
462	
463	    // Collect real DB records for the subject
464	    let dbUserData: Record<string, unknown>[] = [];
465	    let dbAuditData: Record<string, unknown>[] = [];
466	    let dbConversationData: Record<string, unknown>[] = [];
467	    let dbEmotionalData: Record<string, unknown>[] = [];
468	
469	    try {
470	      const db = await getDb();
471	
472	      // User profile data (match by email or openId)
473	      dbUserData = await db
474	        .select()
475	        .from(users)
476	        .where(eq(users.email, request.subjectEmail));
477	
478	      // Governance audit log entries for the subject
479	      if (dbUserData.length > 0) {
480	        const userId = (dbUserData[0] as any).id;
481	        dbAuditData = await db
482	          .select()
483	          .from(governanceAuditLog)
484	          .where(eq(governanceAuditLog.actorId, userId));
485	
486	        dbConversationData = await db
487	          .select()
488	          .from(conversationSessions)
489	          .where(eq(conversationSessions.userId, userId));
490	
491	        dbEmotionalData = await db
492	          .select()
493	          .from(emotionalHistory)
494	          .where(eq(emotionalHistory.userId, userId));
495	      }
496	    } catch (err) {
497	      // DB unavailable — proceed with in-memory data only
498	      this.logAudit("DSR_EXPORT_DB_PARTIAL", "system", `DB query failed during export: ${(err as Error).message}`, request.subjectId);
499	    }
500	
501	    // Create export data bundle
502	    const exportData = {
503	      subjectId: request.subjectId,
504	      subjectEmail: request.subjectEmail,
505	      exportedAt: new Date().toISOString(),
506	      user_profile: dbUserData,
507	      audit_log: dbAuditData,
508	      conversations: dbConversationData,
509	      emotional_history: dbEmotionalData,
510	      retention_records: inMemoryRecords.map(r => ({
511	        category: r.dataCategory,
512	        data: r.data,
513	        createdAt: r.createdAt.toISOString(),
514	      })),
515	    };
516	
517	    const exportUrl = `data:application/json;base64,${Buffer.from(JSON.stringify(exportData)).toString("base64")}`;
518	    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days
519	
520	    const totalRecords = dbUserData.length + dbAuditData.length + dbConversationData.length + dbEmotionalData.length + inMemoryRecords.length;
521	
522	    return {
523	      exportUrl,
524	      exportExpiresAt: expiresAt,
525	      deletedRecords: 0,
526	      retainedRecords: totalRecords,
527	      retentionReason: null,
528	      verificationHash: crypto.createHash("sha256").update(JSON.stringify(exportData)).digest("hex"),
529	      completedAt: new Date(),
530	    };
531	  }
532	
533	  /**
534	   * Process delete request (right to be forgotten).
535	   * Deletes user data from DB tables and in-memory records.
536	   */
537	  private async processDeleteRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
538	    let deletedCount = 0;
539	    let retainedCount = 0;
540	    const retentionReasons: string[] = [];
541	
542	    // ----- Delete from real DB tables -----
543	    try {
544	      const db = await getDb();
545	
546	      // Find the user by email
547	      const userRows = await db
548	        .select()
549	        .from(users)
550	        .where(eq(users.email, request.subjectEmail));
551	
552	      if (userRows.length > 0) {
553	        const userId = userRows[0].id;
554	
555	        // Delete emotional history
556	        const emotionalDel = await db.delete(emotionalHistory).where(eq(emotionalHistory.userId, userId));
557	        deletedCount += (emotionalDel as any).rowCount ?? 0;
558	
559	        // Delete emotional patterns
560	        const patternDel = await db.delete(emotionalPatterns).where(eq(emotionalPatterns.userId, userId));
561	        deletedCount += (patternDel as any).rowCount ?? 0;
562	
563	        // Delete conversation turns for user's sessions
564	        const userSessions = await db.select().from(conversationSessions).where(eq(conversationSessions.userId, userId));
565	        for (const session of userSessions) {
566	          const turnDel = await db.delete(conversationTurns).where(eq(conversationTurns.sessionId, session.sessionId));
567	          deletedCount += (turnDel as any).rowCount ?? 0;
568	        }
569	
570	        // Delete conversation sessions
571	        const sessionDel = await db.delete(conversationSessions).where(eq(conversationSessions.userId, userId));
572	        deletedCount += (sessionDel as any).rowCount ?? 0;
573	
574	        // Delete API usage records
575	        const usageDel = await db.delete(apiUsage).where(eq(apiUsage.userId, userId));
576	        deletedCount += (usageDel as any).rowCount ?? 0;
577	
578	        // Governance audit log: retain for compliance but anonymize
579	        const auditRows = await db
580	          .select()
581	          .from(governanceAuditLog)
582	          .where(eq(governanceAuditLog.actorId, userId));
583	        if (auditRows.length > 0) {
584	          retainedCount += auditRows.length;
585	          retentionReasons.push(`${auditRows.length} governance audit log entries: Compliance requirement — anonymized`);
586	          // Anonymize the actor field
587	          await db
588	            .update(governanceAuditLog)
589	            .set({ actor: "[DELETED_USER]" } as any)
590	            .where(eq(governanceAuditLog.actorId, userId));
591	        }
592	
593	        // Delete the user record itself
594	        await db.delete(users).where(eq(users.id, userId));
595	        deletedCount += 1;
596	      }
597	    } catch (err) {
598	      this.logAudit("DSR_DELETE_DB_ERROR", "system", `DB deletion failed: ${(err as Error).message}`, request.subjectId);
599	      retentionReasons.push(`DB deletion error: ${(err as Error).message}`);
600	    }
601	
602	    // ----- Delete in-memory records -----
603	    const inMemoryRecords = this.getRecordsForSubject(request.orgId, request.subjectId);
604	    for (const record of inMemoryRecords) {
605	      const policy = this.policies.get(record.retentionPolicyId);
606	
607	      if (record.legalHold || policy?.legalHoldEnabled) {
608	        retainedCount++;
609	        retentionReasons.push(`Record ${record.recordId}: Legal hold`);
610	        continue;
611	      }
612	
613	      if (record.dataCategory === "audit_logs" && policy?.complianceFramework !== "custom") {
614	        retainedCount++;
615	        retentionReasons.push(`Record ${record.recordId}: Compliance requirement`);
616	        continue;
617	      }
618	
619	      record.deletedAt = new Date();
620	      deletedCount++;
621	    }
622	
623	    return {
624	      exportUrl: null,
625	      exportExpiresAt: null,
626	      deletedRecords: deletedCount,
627	      retainedRecords: retainedCount,
628	      retentionReason: retentionReasons.length > 0 ? retentionReasons.join("; ") : null,
629	      verificationHash: crypto.createHash("sha256").update(`deleted:${deletedCount}:retained:${retainedCount}`).digest("hex"),
630	      completedAt: new Date(),
631	    };
632	  }
633	
634	  /**
635	   * Process access request (right of access)
636	   */
637	  private async processAccessRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
638	    // Same as export but without download
639	    return this.processExportRequest(request);
640	  }
641	
642	  /**
643	   * Process restrict request (right to restriction)
644	   */
645	  private async processRestrictRequest(request: DataSubjectRequest): Promise<DataSubjectResult> {
646	    const records = this.getRecordsForSubject(request.orgId, request.subjectId);
647	    
648	    // Mark all records as restricted (legal hold)
649	    for (const record of records) {
650	      record.legalHold = true;
651	    }
652	    
653	    return {
654	      exportUrl: null,
655	      exportExpiresAt: null,
656	      deletedRecords: 0,
657	      retainedRecords: records.length,
658	      retentionReason: "Processing restricted per subject request",
659	      verificationHash: crypto.createHash("sha256").update(`restricted:${records.length}`).digest("hex"),
660	      completedAt: new Date(),
661	    };
662	  }
663	
664	  /**
665	   * Get pending DSRs
666	   */
667	  getPendingDSRs(orgId: string): DataSubjectRequest[] {
668	    return Array.from(this.requests.values())
669	      .filter(r => r.orgId === orgId && r.status === "pending");
670	  }
671	
672	  /**
673	   * Get overdue DSRs
674	   */
675	  getOverdueDSRs(orgId: string): DataSubjectRequest[] {
676	    const now = new Date();
677	    return Array.from(this.requests.values())
678	      .filter(r => r.orgId === orgId && r.status === "pending" && r.deadline < now);
679	  }
680	
681	  // ============================================================================
682	  // COMPLIANCE REPORTING
683	  // ============================================================================
684	
685	  /**
686	   * Generate compliance report
687	   */
688	  generateComplianceReport(params: {
689	    orgId: string;
690	    framework: RetentionPolicy["complianceFramework"];
691	    startDate: Date;
692	    endDate: Date;
693	    generatedBy: string;
694	  }): ComplianceReport {
695	    const records = Array.from(this.records.values())
696	      .filter(r => r.orgId === params.orgId);
697	    
698	    const dsrs = Array.from(this.requests.values())
699	      .filter(r => r.orgId === params.orgId && 
700	        r.requestedAt >= params.startDate && 
701	        r.requestedAt <= params.endDate);
702	    
703	    // Calculate metrics
704	    const totalRecords = records.length;
705	    const expiredRecords = records.filter(r => r.expiresAt < new Date()).length;
706	    const archivedRecords = records.filter(r => r.archivedAt).length;
707	    const deletedRecords = records.filter(r => r.deletedAt).length;
708	    
709	    const completedDSRs = dsrs.filter(r => r.status === "completed");
710	    const responseTimes = completedDSRs
711	      .filter(r => r.completedAt)
712	      .map(r => r.completedAt!.getTime() - r.requestedAt.getTime());
713	    const averageResponseTime = responseTimes.length > 0
714	      ? responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length / (24 * 60 * 60 * 1000)
715	      : 0;
716	    
717	    // Identify issues
718	    const issues: string[] = [];
719	    const recommendations: string[] = [];
720	    
721	    const overdueDSRs = this.getOverdueDSRs(params.orgId);
722	    if (overdueDSRs.length > 0) {
723	      issues.push(`${overdueDSRs.length} overdue DSR(s) require immediate attention`);
724	      recommendations.push("Process overdue DSRs immediately to avoid compliance violations");
725	    }
726	    
727	    if (averageResponseTime > 25) {
728	      issues.push(`Average DSR response time (${averageResponseTime.toFixed(1)} days) approaching deadline`);
729	      recommendations.push("Implement automated DSR processing to reduce response time");
730	    }
731	    
732	    const policiesWithoutLegalHold = this.getPolicies(params.orgId)
733	      .filter(p => !p.legalHoldEnabled && p.dataCategory === "audit_logs");
734	    if (policiesWithoutLegalHold.length > 0) {
735	      recommendations.push("Consider enabling legal hold on audit log policies for compliance");
736	    }
737	    
738	    return {
739	      reportId: crypto.randomUUID(),
740	      orgId: params.orgId,
741	      framework: params.framework,
742	      reportPeriod: { start: params.startDate, end: params.endDate },
743	      totalRecords,
744	      expiredRecords,
745	      archivedRecords,
746	      deletedRecords,
747	      totalDSRs: dsrs.length,
748	      completedDSRs: completedDSRs.length,
749	      averageResponseTime,
750	      issues,
751	      recommendations,
752	      generatedAt: new Date(),
753	      generatedBy: params.generatedBy,
754	    };
755	  }
756	
757	  // ============================================================================
758	  // AUDIT LOG
759	  // ============================================================================
760	
761	  /**
762	   * Get audit log
763	   */
764	  getAuditLog(params?: {
765	    orgId?: string;
766	    subjectId?: string;
767	    startDate?: Date;
768	    endDate?: Date;
769	  }): typeof this.auditLog {
770	    let log = [...this.auditLog];
771	    
772	    if (params?.subjectId) {
773	      log = log.filter(e => e.subjectId === params.subjectId);
774	    }
775	    
776	    if (params?.startDate) {
777	      log = log.filter(e => e.timestamp >= params.startDate!);
778	    }
779	    
780	    if (params?.endDate) {
781	      log = log.filter(e => e.timestamp <= params.endDate!);
782	    }
783	    
784	    return log;
785	  }
786	
787	  // ============================================================================
788	  // PRIVATE HELPERS
789	  // ============================================================================
790	
791	  /**
792	   * Update a DSR record in the database.
793	   */
794	  private async updateDSRInDb(
795	    requestId: string,
796	    fields: { status?: string; processedBy?: string; completedAt?: Date | null; result?: string | null; notes?: string },
797	  ): Promise<void> {
798	    try {
799	      const db = await getDb();
800	      await db
801	        .update(dataSubjectRequests)
802	        .set({
803	          ...(fields.status !== undefined && { status: fields.status }),
804	          ...(fields.processedBy !== undefined && { processedBy: fields.processedBy }),
805	          ...(fields.completedAt !== undefined && { completedAt: fields.completedAt }),
806	          ...(fields.result !== undefined && { result: fields.result }),
807	          ...(fields.notes !== undefined && { notes: fields.notes }),
808	          updatedAt: new Date(),
809	        })
810	        .where(eq(dataSubjectRequests.id, requestId));
811	    } catch (err) {
812	      this.logAudit("DSR_DB_UPDATE_FAILED", "system", `Failed to update DSR ${requestId} in DB: ${(err as Error).message}`, null);
813	    }
814	  }
815	
816	  private logAudit(action: string, actor: string, details: string, subjectId: string | null): void {
817	    this.auditLog.push({
818	      timestamp: new Date(),
819	      action,
820	      actor,
821	      details,
822	      subjectId,
823	    });
824	  }
825	
826	  /**
827	   * Clear all data (for testing)
828	   */
829	  clear(): void {
830	    this.policies.clear();
831	    this.requests.clear();
832	    this.records.clear();
833	    this.auditLog = [];
834	  }
835	}
836	
837	// ============================================================================
838	// SINGLETON INSTANCE
839	// ============================================================================
840	
841	export const dataRetentionService = new DataRetentionService();
